const config = {
  "previewFeatures": [],
  "clientVersion": "7.4.2",
  "engineVersion": "94a226be1cf2967af2541cca5529f0f7ba866919",
  "activeProvider": "postgresql",
  "inlineSchema": "// =============================================================\n// DailyUse Database Schema — Base Configuration\n// =============================================================\n//\n// This file contains the generator and datasource configuration\n// All model files in this folder will be automatically included\n// =============================================================\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ==========================================\n// Account Module\n// 账户聚合根\n// ==========================================\n\nmodel Account {\n  id               String    @id // same as AuthIdentity.id\n  status           String    @default(\"ACTIVE\") // AccountStatus: ACTIVE | INACTIVE | SUSPENDED | DELETED\n  // profile\n  profile          Json\n  // settings\n  settings         Json\n  // email object value\n  emailAddress     String    @unique @map(\"email_address\") // jdoe@example.com\n  emailIsVerified  Boolean   @default(false) @map(\"email_is_verified\")\n  emailVerifiedAt  DateTime? @map(\"email_verified_at\")\n  emailIsPrimary   Boolean   @default(false) @map(\"email_is_primary\")\n  // phone object value\n  phoneCountryCode String?   @map(\"phone_country_code\") // +86\n  phoneNumber      String?   @map(\"phone_number\") // 13800138000\n  phoneFullNumber  String?   @map(\"phone_full_number\") // +8613800138000 (E.164格式)\n  phoneIsVerified  Boolean?  @default(false) @map(\"phone_is_verified\")\n  phoneVerifiedAt  DateTime? @map(\"phone_verified_at\")\n  version          Int       @default(1)\n  createdAt        DateTime  @default(now()) @map(\"created_at\")\n  updatedAt        DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt        DateTime? @map(\"deleted_at\")\n\n  // 关联关系\n  identity AuthIdentity @relation(fields: [id], references: [id], onDelete: Cascade)\n\n  // 关联的业务模块\n  documents                       Document[]\n  documentVersions                DocumentVersion[]                @relation(\"AccountDocumentVersionChangedBy\")\n  editorWorkspaces                EditorWorkspace[]\n  editorWorkspaceSessions         EditorWorkspaceSession[]\n  editorWorkspaceSessionGroups    EditorWorkspaceSessionGroup[]\n  editorWorkspaceSessionGroupTabs EditorWorkspaceSessionGroupTab[]\n  focusSessions                   FocusSession[]\n  focusModes                      FocusMode[]\n  goals                           Goal[]\n  goalFolders                     GoalFolder[]\n  goalStatistics                  GoalStatistic?\n  reminderGroups                  ReminderGroup[]\n  reminderTemplates               ReminderTemplate[]\n  reminderInstances               ReminderInstance[]\n  reminderStatistics              ReminderStatistic?\n  userReminderPreferences         UserReminderPreference?\n  repositories                    Repository[]\n  repositoryExplorers             RepositoryExplorer[]\n  repositoryStatistics            RepositoryStatistic?\n  schedules                       Schedule[]\n  scheduleJobs                    ScheduleJob[]\n  scheduleTasks                   ScheduleTask[]\n  scheduleStatistics              ScheduleStatistic?\n  taskFolders                     TaskFolder[]\n  taskTemplates                   TaskTemplate[]\n  taskInstances                   TaskInstance[]\n  taskStatistics                  TaskStatistic?\n  userSettings                    UserSetting?\n  notifications                   Notification[]\n  aiConversations                 AiConversation[]\n  aiGenerationTasks               AiGenerationTask[]\n  aiUsageQuotas                   AiUsageQuota?\n  aiProviderConfigs               AiProviderConfig[]\n  dashboardConfigs                DashboardConfig?\n\n  // PowerSync: denormalized identity relations\n  keyResults                 KeyResult[]               @relation(\"AccountKeyResults\")\n  goalRecords                GoalRecord[]              @relation(\"AccountGoalRecords\")\n  goalReviews                GoalReview[]              @relation(\"AccountGoalReviews\")\n  keyResultWeightSnapshots   KeyResultWeightSnapshot[] @relation(\"AccountKeyResultWeightSnapshots\")\n  taskDependencies           TaskDependency[]          @relation(\"AccountTaskDependencies\")\n  taskTemplateHistory        TaskTemplateHistory[]     @relation(\"AccountTaskTemplateHistory\")\n  scheduleExecutions         ScheduleExecution[]       @relation(\"AccountScheduleExecutions\")\n  reminderHistory            ReminderHistory[]         @relation(\"AccountReminderHistory\")\n  reminderResponses          ReminderResponse[]        @relation(\"AccountReminderResponses\")\n  notificationChannels       NotificationChannel[]     @relation(\"AccountNotificationChannels\")\n  notificationHistory        NotificationHistory[]     @relation(\"AccountNotificationHistory\")\n  documentVersionsByIdentity DocumentVersion[]         @relation(\"AccountDocumentVersions\")\n  documentLinks              DocumentLink[]            @relation(\"AccountDocumentLinks\")\n  aiMessages                 AiMessage[]               @relation(\"AccountAiMessages\")\n  folders                    Folder[]                  @relation(\"AccountFolders\")\n  resources                  Resource[]                @relation(\"AccountResources\")\n  repositoryResources        RepositoryResource[]      @relation(\"AccountRepositoryResources\")\n\n  @@index([emailAddress])\n  @@index([phoneFullNumber])\n  @@map(\"accounts\")\n}\n\n// ==========================================\n// AI Module\n// AI 对话、消息、生成任务、配额、Provider 配置\n// ==========================================\n\nmodel AiConversation {\n  id            String    @id\n  identityId    String    @map(\"identity_id\")\n  name          String\n  status        String // ACTIVE, CLOSED, ARCHIVED\n  messageCount  Int       @default(0) @map(\"message_count\")\n  lastMessageAt DateTime? @map(\"last_message_at\")\n  version       Int       @default(1)\n  createdAt     DateTime  @default(now()) @map(\"created_at\")\n  updatedAt     DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt     DateTime? @map(\"deleted_at\")\n\n  account  Account     @relation(fields: [identityId], references: [id], onDelete: Cascade)\n  messages AiMessage[]\n\n  @@index([identityId])\n  @@index([status])\n  @@index([createdAt])\n  @@index([lastMessageAt])\n  @@map(\"ai_conversations\")\n}\n\nmodel AiMessage {\n  id             String   @id\n  identityId     String   @map(\"identity_id\")\n  conversationId String   @map(\"conversation_id\")\n  role           String // USER, ASSISTANT, SYSTEM\n  content        String   @db.Text\n  tokenUsage     String?  @map(\"token_usage\") // JSON\n  createdAt      DateTime @default(now()) @map(\"created_at\")\n\n  identity     Account        @relation(\"AccountAiMessages\", fields: [identityId], references: [id])\n  conversation AiConversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n\n  @@index([identityId])\n  @@index([conversationId])\n  @@index([createdAt])\n  @@map(\"ai_messages\")\n}\n\nmodel AiGenerationTask {\n  id           String    @id\n  identityId   String    @map(\"identity_id\")\n  taskType     String    @map(\"task_type\") // GOAL_KEY_RESULTS, TASK_TEMPLATES, etc.\n  status       String // PENDING, PROCESSING, COMPLETED, FAILED\n  input        String    @db.Text // JSON string\n  result       String?   @db.Text // JSON string\n  error        String?   @db.Text\n  retryCount   Int       @default(0) @map(\"retry_count\")\n  tokenUsage   String?   @map(\"token_usage\") // JSON\n  processingMs Int?      @map(\"processing_ms\")\n  version      Int       @default(1)\n  createdAt    DateTime  @default(now()) @map(\"created_at\")\n  updatedAt    DateTime  @updatedAt @map(\"updated_at\")\n  completedAt  DateTime? @map(\"completed_at\")\n  deletedAt    DateTime? @map(\"deleted_at\")\n\n  account Account @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  @@index([identityId])\n  @@index([taskType])\n  @@index([status])\n  @@index([createdAt])\n  @@map(\"ai_generation_tasks\")\n}\n\nmodel AiUsageQuota {\n  id           String    @id\n  identityId   String    @unique @map(\"identity_id\")\n  quotaLimit   Int       @default(50) @map(\"quota_limit\")\n  currentUsage Int       @default(0) @map(\"current_usage\")\n  resetPeriod  String    @default(\"DAILY\") @map(\"reset_period\") // DAILY, WEEKLY, MONTHLY\n  lastResetAt  DateTime  @default(now()) @map(\"last_reset_at\")\n  nextResetAt  DateTime  @map(\"next_reset_at\")\n  version      Int       @default(1)\n  createdAt    DateTime  @default(now()) @map(\"created_at\")\n  updatedAt    DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt    DateTime? @map(\"deleted_at\")\n\n  account Account @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  @@index([identityId])\n  @@index([nextResetAt])\n  @@map(\"ai_usage_quotas\")\n}\n\nmodel AiProviderConfig {\n  id              String    @id\n  identityId      String    @map(\"identity_id\")\n  name            String // 配置名称\n  providerType    String    @map(\"provider_type\") // OPENAI, QINIU, ANTHROPIC, CUSTOM_OPENAI_COMPATIBLE\n  baseUrl         String    @map(\"base_url\") // API 基础地址\n  apiKeyEncrypted String    @map(\"api_key_encrypted\") // AES-256-GCM 加密的 API Key\n  defaultModel    String?   @map(\"default_model\")\n  availableModels String    @default(\"[]\") @map(\"available_models\") // 可用模型列表 JSON\n  isActive        Boolean   @default(true) @map(\"is_active\")\n  isDefault       Boolean   @default(false) @map(\"is_default\")\n  priority        Int       @default(100) // 优先级\n  version         Int       @default(1)\n  createdAt       DateTime  @default(now()) @map(\"created_at\")\n  updatedAt       DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt       DateTime? @map(\"deleted_at\")\n\n  account Account @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  @@unique([identityId, name])\n  @@index([identityId])\n  @@index([isDefault])\n  @@index([isActive])\n  @@index([priority])\n  @@map(\"ai_provider_configs\")\n}\n\nmodel KnowledgeGenerationTask {\n  id                   String    @id\n  identityId           String    @map(\"identity_id\")\n  topic                String\n  documentCount        Int       @default(5) @map(\"document_count\")\n  targetAudience       String?   @map(\"target_audience\")\n  folderPath           String    @map(\"folder_path\")\n  status               String // PENDING, GENERATING, COMPLETED, FAILED\n  progress             Int       @default(0) // 0-100\n  generatedDocumentIds String[]  @map(\"generated_document_ids\")\n  error                String?   @db.Text\n  createdAt            DateTime  @default(now()) @map(\"created_at\")\n  completedAt          DateTime? @map(\"completed_at\")\n\n  @@index([identityId])\n  @@index([status])\n  @@index([createdAt])\n  @@map(\"knowledge_generation_tasks\")\n}\n\nmodel DashboardConfig {\n  id           Int      @id @default(autoincrement())\n  identityId   String   @unique @map(\"identity_id\")\n  widgetConfig Json     @map(\"widget_config\")\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n  updatedAt    DateTime @updatedAt @map(\"updated_at\")\n\n  account Account @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  @@index([identityId])\n  @@map(\"dashboard_configs\")\n}\n\n// ==========================================\n// Auth Module\n// 认证聚合根、标识符、绑定、凭证、会话\n// ==========================================\n\n// 1. 取消 Prisma 枚举，统一存储大驼峰字符串\n\n// ==========================================\n// 1. 身份聚合根表 (AuthIdentity)\n// ==========================================\nmodel AuthIdentity {\n  id     String @id @default(uuid())\n  status String @default(\"Unverified\")\n\n  // 安全风控字段 (对应聚合根内部状态)\n  failedLoginAttempts Int       @default(0) @map(\"failed_login_attempts\")\n  lastFailedAttempt   DateTime? @map(\"last_failed_attempt\")\n  lockedUntil         DateTime? @map(\"locked_until\")\n\n  // 时间戳\n  version   Int       @default(1)\n  createdAt DateTime  @default(now()) @map(\"created_at\")\n  updatedAt DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt DateTime? @map(\"deleted_at\")\n\n  // 关联\n  identifiers   AuthIdentifier[]\n  oauthBindings AuthOAuthBinding[]\n  credentials   AuthCredential[]\n  sessions      AuthSession[]\n  accounts      Account[]\n\n  @@map(\"auth_identities\")\n}\n\n// ==========================================\n// 2. 标识符表 (AuthIdentifier)\n// 存储邮箱/手机号等值对象标识符\n// 解决\"如何找到用户\"\n// ==========================================\nmodel AuthIdentifier {\n  id         String   @id @default(uuid())\n  identityId String   @map(\"identity_id\")\n  type       String // 'EMAIL' | 'PHONE'\n  value      String // 邮箱地址或手机号\n  isVerified Boolean  @default(false) @map(\"is_verified\")\n  createdAt  DateTime @default(now()) @map(\"created_at\")\n\n  identity AuthIdentity @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  @@unique([identityId, type, value])\n  @@index([type, value]) // findByEmail / findByPhone 的查询索引\n  @@map(\"auth_identifiers\")\n}\n\n// ==========================================\n// 3. OAuth 绑定表 (AuthOAuthBinding)\n// Entity 形式的标识符，拥有独立 ID 和可变 Token 状态\n// 解决\"通过第三方如何找到用户\"\n// ==========================================\nmodel AuthOAuthBinding {\n  id                String    @id @default(uuid())\n  identityId        String    @map(\"identity_id\")\n  provider          String // GOOGLE, GITHUB 等\n  providerSubjectId String    @map(\"provider_subject_id\")\n  accessToken       String?   @map(\"access_token\")\n  refreshToken      String?   @map(\"refresh_token\")\n  expiresAt         DateTime? @map(\"expires_at\")\n  createdAt         DateTime  @default(now()) @map(\"created_at\")\n  lastUsedAt        DateTime? @map(\"last_used_at\")\n\n  identity AuthIdentity @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  @@unique([provider, providerSubjectId])\n  @@index([identityId])\n  @@map(\"auth_oauth_bindings\")\n}\n\n// ==========================================\n// 4. 凭证实体表 (AuthCredential)\n// 仅保留真正的凭证（密码）\n// 解决\"如何验证用户\"\n// ==========================================\nmodel AuthCredential {\n  id String @id @default(uuid())\n\n  // 归属的身份\n  identityId String       @map(\"identity_id\")\n  identity   AuthIdentity @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  // 核心字段\n  type   String\n  status String @default(\"Active\")\n\n  // [Type: PASSWORD]\n  passwordHash          String?   @map(\"password_hash\") // Argon2 hash\n  passwordLastChangedAt DateTime? @map(\"password_last_changed_at\") // 密码最后修改时间\n\n  // 元数据\n  version    Int       @default(1)\n  createdAt  DateTime  @default(now()) @map(\"created_at\")\n  lastUsedAt DateTime? @map(\"last_used_at\")\n  deletedAt  DateTime? @map(\"deleted_at\")\n\n  @@index([identityId, type])\n  @@map(\"auth_credentials\")\n}\n\n// ==========================================\n// 5. 会话聚合根表 (AuthSession)\n// ==========================================\nmodel AuthSession {\n  id String @id @default(uuid())\n\n  identityId String       @map(\"identity_id\")\n  identity   AuthIdentity @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  // 核心令牌数据\n  refreshTokenHash String? @map(\"refresh_token_hash\") // 支持 Refresh Token 轮换\n\n  // 设备信息 (对应 DeviceInfo Value Object)\n  deviceId          String  @map(\"device_id\")\n  deviceFingerprint String  @map(\"device_fingerprint\")\n  deviceType        String  @map(\"device_type\") // MOBILE, DESKTOP\n  deviceName        String? @map(\"device_name\")\n  os                String?\n  browser           String?\n  ipAddress         String? @map(\"ip_address\")\n\n  // 地理位置 (用 JSON 存比较灵活，因为字段不确定)\n  location Json? // { country, city, timezone }\n\n  // 生命周期\n  version      Int       @default(1)\n  createdAt    DateTime  @default(now()) @map(\"created_at\")\n  expiresAt    DateTime  @map(\"expires_at\")\n  lastActiveAt DateTime  @default(now()) @map(\"last_active_at\")\n  deletedAt    DateTime? @map(\"deleted_at\")\n\n  @@index([identityId])\n  @@index([expiresAt])\n  @@map(\"auth_sessions\")\n}\n\n// ==========================================\n// Document Module\n// 文档聚合根、版本、链接\n// ==========================================\n\nmodel Document {\n  id              String    @id\n  identityId      String    @map(\"identity_id\")\n  title           String\n  content         String    @db.Text\n  folderPath      String    @map(\"folder_path\")\n  tags            String[] // PostgreSQL array\n  status          String    @default(\"DRAFT\") // DRAFT | PUBLISHED | ARCHIVED\n  currentVersion  Int       @default(0) @map(\"current_version\")\n  lastVersionedAt DateTime? @map(\"last_versioned_at\")\n  lastEditedAt    DateTime? @map(\"last_edited_at\")\n  editSessionId   String?   @map(\"edit_session_id\")\n  version         Int       @default(1)\n  createdAt       DateTime  @default(now()) @map(\"created_at\")\n  updatedAt       DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt       DateTime? @map(\"deleted_at\")\n\n  account     Account           @relation(fields: [identityId], references: [id], onDelete: Cascade)\n  versions    DocumentVersion[]\n  sourceLinks DocumentLink[]    @relation(\"source_links\")\n  targetLinks DocumentLink[]    @relation(\"target_links\")\n\n  @@index([identityId, deletedAt])\n  @@index([identityId, folderPath])\n  @@index([identityId, status])\n  @@map(\"documents\")\n}\n\nmodel DocumentVersion {\n  id                String   @id\n  identityId        String   @map(\"identity_id\")\n  documentId        String   @map(\"document_id\")\n  versionNumber     Int      @map(\"version_number\")\n  title             String\n  content           String   @db.Text\n  changeType        String   @map(\"change_type\") // initial | major | minor | patch | restore\n  changeDescription String?  @map(\"change_description\")\n  changedBy         String   @map(\"changed_by\")\n  restoredFrom      String?  @map(\"restored_from\")\n  metadata          Json? // { addedChars, deletedChars, modifiedSections }\n  version           Int      @default(1)\n  createdAt         DateTime @default(now()) @map(\"created_at\")\n\n  document Document @relation(fields: [documentId], references: [id], onDelete: Cascade)\n  identity Account  @relation(\"AccountDocumentVersions\", fields: [identityId], references: [id])\n  account  Account  @relation(\"AccountDocumentVersionChangedBy\", fields: [changedBy], references: [id])\n\n  @@index([identityId])\n  @@index([documentId, versionNumber])\n  @@index([documentId, createdAt])\n  @@index([changedBy])\n  @@map(\"document_versions\")\n}\n\nmodel DocumentLink {\n  id               String    @id\n  identityId       String    @map(\"identity_id\")\n  sourceDocumentId String    @map(\"source_document_id\")\n  targetDocumentId String?   @map(\"target_document_id\")\n  linkText         String    @map(\"link_text\")\n  linkPosition     Int       @map(\"link_position\")\n  isBroken         Boolean   @default(false) @map(\"is_broken\")\n  version          Int       @default(1)\n  createdAt        DateTime  @default(now()) @map(\"created_at\")\n  updatedAt        DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt        DateTime? @map(\"deleted_at\")\n\n  identity       Account   @relation(\"AccountDocumentLinks\", fields: [identityId], references: [id])\n  sourceDocument Document  @relation(\"source_links\", fields: [sourceDocumentId], references: [id], onDelete: Cascade)\n  targetDocument Document? @relation(\"target_links\", fields: [targetDocumentId], references: [id], onDelete: SetNull)\n\n  @@index([identityId])\n  @@index([sourceDocumentId])\n  @@index([targetDocumentId])\n  @@index([isBroken])\n  @@map(\"document_links\")\n}\n\n// ==========================================\n// Editor Module\n// 编辑器工作区、会话、标签页\n// ==========================================\n\nmodel EditorWorkspace {\n  id          String    @id\n  identityId  String    @map(\"identity_id\")\n  name        String\n  description String?\n  projectPath String    @unique @map(\"project_path\")\n  projectType String    @map(\"project_type\")\n  layout      Json\n  setting     Json\n  isActive    Boolean   @default(true) @map(\"is_active\")\n  version     Int       @default(1)\n  createdAt   DateTime  @default(now()) @map(\"created_at\")\n  updatedAt   DateTime  @updatedAt @map(\"updated_at\")\n  accessedAt  DateTime  @default(now()) @map(\"accessed_at\")\n  deletedAt   DateTime? @map(\"deleted_at\")\n\n  sessions EditorWorkspaceSession[]\n  account  Account                  @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  @@index([isActive])\n  @@map(\"editor_workspaces\")\n}\n\nmodel EditorWorkspaceSession {\n  id          String    @id\n  workspaceId String    @map(\"workspace_id\")\n  identityId  String    @map(\"identity_id\")\n  name        String\n  layout      Json\n  isActive    Boolean   @default(true) @map(\"is_active\")\n  version     Int       @default(1)\n  createdAt   DateTime  @default(now()) @map(\"created_at\")\n  updatedAt   DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt   DateTime? @map(\"deleted_at\")\n\n  groups    EditorWorkspaceSessionGroup[]\n  account   Account                       @relation(fields: [identityId], references: [id], onDelete: Cascade)\n  workspace EditorWorkspace               @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n\n  @@index([workspaceId])\n  @@map(\"editor_workspace_sessions\")\n}\n\nmodel EditorWorkspaceSessionGroup {\n  id             String    @id\n  sessionId      String    @map(\"session_id\")\n  workspaceId    String    @map(\"workspace_id\")\n  identityId     String    @map(\"identity_id\")\n  groupIndex     Int       @map(\"group_index\")\n  name           String?\n  splitDirection String    @map(\"split_direction\")\n  version        Int       @default(1)\n  createdAt      DateTime  @default(now()) @map(\"created_at\")\n  updatedAt      DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt      DateTime? @map(\"deleted_at\")\n\n  tabs    EditorWorkspaceSessionGroupTab[]\n  account Account                          @relation(fields: [identityId], references: [id], onDelete: Cascade)\n  session EditorWorkspaceSession           @relation(fields: [sessionId], references: [id], onDelete: Cascade)\n\n  @@index([workspaceId])\n  @@map(\"editor_workspace_session_groups\")\n}\n\nmodel EditorWorkspaceSessionGroupTab {\n  id          String    @id\n  groupId     String    @map(\"group_id\")\n  sessionId   String    @map(\"session_id\")\n  workspaceId String    @map(\"workspace_id\")\n  identityId  String    @map(\"identity_id\")\n  documentId  String?   @map(\"document_id\")\n  tabIndex    Int       @map(\"tab_index\")\n  tabType     String    @map(\"tab_type\")\n  title       String\n  viewState   Json      @map(\"view_state\")\n  isPinned    Boolean   @default(false) @map(\"is_pinned\")\n  isActive    Boolean   @default(false) @map(\"is_active\")\n  version     Int       @default(1)\n  createdAt   DateTime  @default(now()) @map(\"created_at\")\n  updatedAt   DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt   DateTime? @map(\"deleted_at\")\n\n  account Account                     @relation(fields: [identityId], references: [id], onDelete: Cascade)\n  group   EditorWorkspaceSessionGroup @relation(fields: [groupId], references: [id], onDelete: Cascade)\n\n  @@index([workspaceId])\n  @@map(\"editor_workspace_session_group_tabs\")\n}\n\n// ==========================================\n// Goal Module\n// 目标聚合根、关键结果、文件夹、记录、评审、统计\n// ==========================================\n\n/// Goal 聚合根 - 用户目标（OKR）\n/// 管理目标的完整生命周期，包括状态、进度、关键结果等\nmodel Goal {\n  // ============ 主键与外键 ============\n  id         String @id\n  identityId String @map(\"identity_id\")\n\n  // ============ 基础信息 ============\n  name                String /// 目标名称（1-200字符）\n  description         String? /// 详细描述（最多2000字符）\n  color               String  @default(\"#3B82F6\") /// UI 显示颜色（必需，默认蓝色）\n  feasibilityAnalysis String? @map(\"feasibility_analysis\") /// AI 可行性分析结果\n  motivation          String? /// 目标动机说明\n\n  // ============ 状态与优先级 ============\n  status     String   @default(\"pending\") /// 目标状态（pending/active/completed/archived）\n  importance String   @default(\"moderate\") /// 重要性级别（ImportanceLevel）\n  priority   Int      @default(0) /// 动态计算的优先级分数（0-100，用于排序）\n  category   String? /// 目标分类\n  tags       String[] @default([]) /// 标签列表（最多20个，每个最多50字符）\n\n  // ============ 时间管理 ============\n  startDate   DateTime? @map(\"start_date\") /// 开始日期\n  targetDate  DateTime? @map(\"target_date\") /// 目标完成日期\n  completedAt DateTime? @map(\"completed_at\") /// 实际完成时间\n  archivedAt  DateTime? @map(\"archived_at\") /// 归档时间\n\n  // ============ 层级与组织 ============\n  folderId     String? @map(\"folder_id\") /// 所属文件夹\n  parentGoalId String? @map(\"parent_goal_id\") /// 父目标ID（支持目标层级）\n  sortOrder    Int     @default(0) @map(\"sort_order\") /// 排序顺序\n\n  // ============ 扩展功能 ============\n  reminderConfig String? @map(\"reminder_config\") /// 提醒配置（JSON序列化）\n\n  // ============ 版本与审计 ============\n  version   Int       @default(1)\n  createdAt DateTime  @default(now()) @map(\"created_at\")\n  updatedAt DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt DateTime? @map(\"deleted_at\")\n\n  // ============ 关系映射 ============\n  account                  Account                   @relation(fields: [identityId], references: [id], onDelete: Cascade)\n  folder                   GoalFolder?               @relation(fields: [folderId], references: [id])\n  parentGoal               Goal?                     @relation(\"GoalHierarchy\", fields: [parentGoalId], references: [id], onDelete: NoAction, onUpdate: NoAction)\n  childGoals               Goal[]                    @relation(\"GoalHierarchy\")\n  keyResults               KeyResult[] /// 关键结果列表（一对多，级联删除）\n  reviews                  GoalReview[] /// 目标评审记录（一对多，级联删除）\n  keyResultWeightSnapshots KeyResultWeightSnapshot[] /// KR权重快照（一对多，级联删除）\n  focusSessions            FocusSession[] /// 专注会话记录（一对多，级联删除）\n\n  // ============ 索引优化 ============\n  @@index([identityId, status]) /// 按用户+状态查询（常用）\n  @@index([identityId, targetDate]) /// 按用户+截止日期查询（日历视图）\n  @@index([identityId, priority]) /// 按用户+优先级排序（列表视图）\n  @@index([folderId]) /// 按文件夹查询\n  @@index([parentGoalId]) /// 按父目标查询（层级视图）\n  @@index([targetDate]) /// 按截止日期查询（全局日历）\n  @@index([deletedAt]) /// 软删除过滤\n  @@map(\"goals\")\n}\n\n/// GoalFolder 聚合根 - 目标文件夹\n/// 用于组织和分类目标，支持层级结构\nmodel GoalFolder {\n  // ============ 主键与外键 ============\n  id         String @id\n  identityId String @map(\"identity_id\")\n\n  // ============ 基础信息 ============\n  name        String /// 文件夹名称\n  description String? /// 描述说明\n  color       String? /// 显示颜色\n  icon        String? /// 图标标识\n\n  // ============ 文件夹特性 ============\n  folderType     String? @map(\"folder_type\") /// 文件夹类型（系统/用户）\n  isSystemFolder Boolean @default(false) @map(\"is_system_folder\") /// 是否为系统文件夹\n  parentFolderId String? @map(\"parent_folder_id\") /// 父文件夹ID（支持嵌套）\n  sortOrder      Int     @default(0) @map(\"sort_order\") /// 排序顺序\n\n  // ============ 统计信息（冗余字段，提升查询性能） ============\n  goalCount          Int @default(0) @map(\"goal_count\") /// 目标总数\n  completedGoalCount Int @default(0) @map(\"completed_goal_count\") /// 已完成目标数\n\n  // ============ 版本与审计 ============\n  version   Int       @default(1)\n  createdAt DateTime  @default(now()) @map(\"created_at\")\n  updatedAt DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt DateTime? @map(\"deleted_at\")\n\n  // ============ 关系映射 ============\n  account      Account      @relation(fields: [identityId], references: [id], onDelete: Cascade)\n  parentFolder GoalFolder?  @relation(\"GoalFolderHierarchy\", fields: [parentFolderId], references: [id], onDelete: NoAction, onUpdate: NoAction)\n  childFolders GoalFolder[] @relation(\"GoalFolderHierarchy\") /// 子文件夹列表\n  goals        Goal[] /// 包含的目标列表\n\n  // ============ 索引优化 ============\n  @@index([identityId]) /// 按用户查询\n  @@index([parentFolderId]) /// 按父文件夹查询（层级视图）\n  @@index([identityId, isSystemFolder]) /// 用户文件夹分类查询\n  @@map(\"goal_folders\")\n}\n\n/// KeyResult 实体 - 关键结果\n/// 衡量目标进度的具体指标（OKR 中的 KR）\nmodel KeyResult {\n  // ============ 主键与外键 ============\n  id         String @id\n  identityId String @map(\"identity_id\")\n  goalId     String @map(\"goal_id\")\n\n  // ============ 基础信息 ============\n  title       String /// KR 标题\n  description String? /// 详细说明\n\n  // ============ 度量配置 ============\n  valueType         String  @map(\"value_type\") /// 数值类型（numeric/boolean/percentage）\n  aggregationMethod String  @map(\"aggregation_method\") /// 聚合方法（sum/average/latest）\n  targetValue       Float   @map(\"target_value\") /// 目标值\n  currentValue      Float   @default(0) @map(\"current_value\") /// 当前值（冗余字段，提升查询性能）\n  unit              String? /// 单位（如：个、%、小时）\n\n  // ============ 权重与排序 ============\n  weight Int @default(1) /// 权重系数（1-5整数，计算目标进度时使用）\n  order  Int @default(0) /// 显示顺序\n\n  // ============ 版本与审计 ============\n  version   Int       @default(1)\n  createdAt DateTime  @default(now()) @map(\"created_at\")\n  updatedAt DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt DateTime? @map(\"deleted_at\")\n\n  // ============ 关系映射 ============\n  identity                 Account                   @relation(\"AccountKeyResults\", fields: [identityId], references: [id])\n  goal                     Goal                      @relation(fields: [goalId], references: [id], onDelete: Cascade)\n  records                  GoalRecord[] /// 记录历史数据（一对多，级联删除）\n  keyResultWeightSnapshots KeyResultWeightSnapshot[] /// 权重变更快照（一对多，级联删除）\n\n  // ============ 索引优化 ============\n  @@index([identityId])\n  @@index([goalId]) /// 按目标查询KR列表\n  @@index([goalId, order]) /// 按目标查询并按顺序排序\n  @@map(\"key_results\")\n}\n\n/// GoalRecord 实体 - 关键结果记录\n/// 记录 KR 的历史数据点，用于趋势分析和进度跟踪\nmodel GoalRecord {\n  // ============ 主键与外键 ============\n  id          String @id\n  identityId  String @map(\"identity_id\")\n  keyResultId String @map(\"key_result_id\")\n\n  // ============ 记录数据 ============\n  value      Float /// 记录的数值\n  note       String? /// 备注说明\n  recordedAt DateTime @map(\"recorded_at\") /// 记录时间（业务时间，非创建时间）\n\n  // ============ 版本与审计 ============\n  version   Int       @default(1)\n  createdAt DateTime  @default(now()) @map(\"created_at\")\n  updatedAt DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt DateTime? @map(\"deleted_at\")\n\n  // ============ 关系映射 ============\n  identity  Account   @relation(\"AccountGoalRecords\", fields: [identityId], references: [id])\n  keyResult KeyResult @relation(fields: [keyResultId], references: [id], onDelete: Cascade)\n\n  // ============ 索引优化 ============\n  @@index([identityId])\n  @@index([keyResultId, recordedAt]) /// 按KR查询时间序列数据（常用）\n  @@index([recordedAt]) /// 按时间查询全局记录\n  @@map(\"goal_records\")\n}\n\n/// GoalReview 实体 - 目标评审\n/// 记录目标的回顾与反思（复盘）\nmodel GoalReview {\n  // ============ 主键与外键 ============\n  id         String @id\n  identityId String @map(\"identity_id\")\n  goalId     String @map(\"goal_id\")\n\n  // ============ 评审内容 ============\n  reviewType     String  @map(\"review_type\") /// 评审类型（weekly/monthly/milestone/completion）\n  content        String /// 主要内容\n  achievements   String? /// 成就总结\n  challenges     String? /// 遇到的挑战\n  lessonsLearned String? @map(\"lessons_learned\") /// 经验教训\n  nextSteps      String? @map(\"next_steps\") /// 下一步计划\n  rating         Int? /// 评分（1-5星）\n\n  // ============ 版本与审计 ============\n  version   Int       @default(1)\n  createdAt DateTime  @default(now()) @map(\"created_at\")\n  updatedAt DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt DateTime? @map(\"deleted_at\")\n\n  // ============ 关系映射 ============\n  identity Account @relation(\"AccountGoalReviews\", fields: [identityId], references: [id])\n  goal     Goal    @relation(fields: [goalId], references: [id], onDelete: Cascade)\n\n  // ============ 索引优化 ============\n  @@index([identityId])\n  @@index([goalId, createdAt]) /// 按目标查询评审时间线（常用）\n  @@index([reviewType]) /// 按评审类型分类查询\n  @@map(\"goal_reviews\")\n}\n\n/// KeyResultWeightSnapshot 值对象 - KR权重快照\n/// 记录关键结果权重的历史变更，用于审计和回溯分析\nmodel KeyResultWeightSnapshot {\n  // ============ 主键与外键 ============\n  id          String @id\n  identityId  String @map(\"identity_id\")\n  goalId      String @map(\"goal_id\")\n  keyResultId String @map(\"key_result_id\")\n\n  // ============ 权重变更数据 ============\n  oldWeight   Int @map(\"old_weight\") /// 旧权重值（1-5整数）\n  newWeight   Int @map(\"new_weight\") /// 新权重值（1-5整数）\n  weightDelta Int @map(\"weight_delta\") /// 权重变化量（新-旧）\n\n  // ============ 变更元数据 ============\n  snapshotTime DateTime @map(\"snapshot_time\") /// 快照时间\n  trigger      String /// 触发原因（manual/auto/normalize）\n  reason       String? /// 变更原因说明\n  operatorId   String   @map(\"operator_id\") /// 操作人ID\n\n  // ============ 审计 ============\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  // ============ 关系映射 ============\n  identity  Account   @relation(\"AccountKeyResultWeightSnapshots\", fields: [identityId], references: [id])\n  goal      Goal      @relation(fields: [goalId], references: [id], onDelete: Cascade)\n  keyResult KeyResult @relation(fields: [keyResultId], references: [id], onDelete: Cascade)\n\n  // ============ 索引优化 ============\n  @@index([identityId])\n  @@index([goalId, snapshotTime]) /// 按目标查询权重变更历史（常用）\n  @@index([keyResultId, snapshotTime]) /// 按KR查询权重变更历史\n  @@index([snapshotTime]) /// 按时间查询全局快照\n  @@map(\"key_result_weight_snapshots\")\n}\n\n/// FocusSession 聚合根 - 专注会话\n/// 管理番茄钟/专注时间的完整生命周期，支持暂停/恢复/完成等状态转换\nmodel FocusSession {\n  // ============ 主键与外键 ============\n  id         String  @id\n  identityId String  @map(\"identity_id\")\n  goalId     String? @map(\"goal_id\") /// 关联的目标ID（可选）\n\n  // ============ 状态与时长 ============\n  status                String  @default(\"Active\") /// 会话状态（Active/Completed/Cancelled）\n  durationMinutes       Int     @map(\"duration_minutes\") /// 计划时长（分钟）\n  actualDurationMinutes Int     @default(0) @map(\"actual_duration_minutes\") /// 实际时长（分钟，排除暂停）\n  description           String? /// 会话描述/备注\n\n  // ============ 时间追踪 ============\n  startedAt   DateTime? @map(\"started_at\") /// 开始时间\n  pausedAt    DateTime? @map(\"paused_at\") /// 最后暂停时间\n  resumedAt   DateTime? @map(\"resumed_at\") /// 最后恢复时间\n  completedAt DateTime? @map(\"completed_at\") /// 完成时间\n  cancelledAt DateTime? @map(\"cancelled_at\") /// 取消时间\n\n  // ============ 暂停统计 ============\n  pauseCount            Int @default(0) @map(\"pause_count\") /// 暂停次数\n  pausedDurationMinutes Int @default(0) @map(\"paused_duration_minutes\") /// 累计暂停时长（分钟）\n\n  // ============ 版本与审计 ============\n  version   Int       @default(1)\n  createdAt DateTime  @default(now()) @map(\"created_at\")\n  updatedAt DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt DateTime? @map(\"deleted_at\")\n\n  // ============ 关系映射 ============\n  account Account @relation(fields: [identityId], references: [id], onDelete: Cascade)\n  goal    Goal?   @relation(fields: [goalId], references: [id], onDelete: SetNull) /// 目标删除时解除关联\n\n  // ============ 索引优化 ============\n  @@index([identityId, status]) /// 按用户+状态查询（常用）\n  @@index([identityId, createdAt]) /// 按用户+时间查询（统计分析）\n  @@index([goalId]) /// 按目标查询专注记录\n  @@index([status]) /// 按状态查询（全局统计）\n  @@index([completedAt]) /// 按完成时间查询（报表统计）\n  @@map(\"focus_sessions\")\n}\n\n/// FocusMode 值对象 - 专注模式\n/// 用户在特定时间段内聚焦于少数目标（1-3个），隐藏其他目标以减少干扰\nmodel FocusMode {\n  // ============ 主键与外键 ============\n  id         String @id\n  identityId String @map(\"identity_id\")\n\n  // ============ 聚焦配置 ============\n  focusedGoalIds  String[] @map(\"focused_goal_ids\") /// 聚焦的目标ID列表（1-3个）\n  hiddenGoalsMode String   @map(\"hidden_goals_mode\") /// 隐藏模式（hide/dim/collapse）\n\n  // ============ 时间范围 ============\n  startTime     DateTime  @map(\"start_time\") /// 开始时间\n  endTime       DateTime  @map(\"end_time\") /// 计划结束时间\n  actualEndTime DateTime? @map(\"actual_end_time\") /// 实际结束时间（提前结束或延长）\n\n  // ============ 状态 ============\n  isActive Boolean @default(true) @map(\"is_active\") /// 是否激活中\n\n  // ============ 版本与审计 ============\n  version   Int       @default(1)\n  createdAt DateTime  @default(now()) @map(\"created_at\")\n  updatedAt DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt DateTime? @map(\"deleted_at\")\n\n  // ============ 关系映射 ============\n  account Account @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  // ============ 索引优化 ============\n  @@index([identityId, isActive]) /// 按用户查询激活状态（常用）\n  @@index([identityId, endTime]) /// 按用户+结束时间查询（历史记录）\n  @@index([isActive]) /// 查询全局激活的专注模式\n  @@index([endTime]) /// 按结束时间查询（清理过期模式）\n  @@map(\"focus_modes\")\n}\n\n/// GoalStatistic 值对象 - 目标统计\n/// 缓存目标模块的统计数据，定期更新\nmodel GoalStatistic {\n  // ============ 主键与外键 ============\n  id         String @id\n  identityId String @unique @map(\"identity_id\")\n\n  // ============ 目标统计 ============\n  totalGoals     Int @default(0) @map(\"total_goals\")\n  activeGoals    Int @default(0) @map(\"active_goals\")\n  completedGoals Int @default(0) @map(\"completed_goals\")\n  archivedGoals  Int @default(0) @map(\"archived_goals\")\n\n  // ============ KR 统计 ============\n  totalKeyResults     Int @default(0) @map(\"total_key_results\")\n  completedKeyResults Int @default(0) @map(\"completed_key_results\")\n\n  // ============ 专注统计 ============\n  totalFocusSessions Int @default(0) @map(\"total_focus_sessions\")\n  totalFocusMinutes  Int @default(0) @map(\"total_focus_minutes\")\n\n  // ============ 评审统计 ============\n  totalReviews  Int    @default(0) @map(\"total_reviews\")\n  averageRating Float? @map(\"average_rating\")\n\n  // ============ 时间 ============\n  calculatedAt DateTime @map(\"calculated_at\")\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n  updatedAt    DateTime @updatedAt @map(\"updated_at\")\n\n  // ============ 关系映射 ============\n  account Account @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  // ============ 索引优化 ============\n  @@index([identityId])\n  @@map(\"goal_statistics\")\n}\n\n// ==========================================\n// Governance Module\n// 规则管理、规则修订记录\n// ==========================================\n\n// ==========================================\n// 1. 规则聚合根表 (Rule)\n// ==========================================\nmodel Rule {\n  id          String @id @default(uuid())\n  code        String @unique // 规则编码，格式：PREFIX-NUMBER (e.g., DDD-001)\n  title       String // 规则标题\n  description String // 规则描述\n\n  severity String @default(\"Recommended\") // Mandatory | Recommended\n  status   String @default(\"Draft\") // Draft | Active | Deprecated\n\n  deprecationReason     String? @map(\"deprecation_reason\")\n  replacementRuleId     String? @map(\"replacement_rule_id\")\n  liveReferenceLocation String? @map(\"live_reference_location\")\n\n  // JSON fields\n  tags         String // JSON array of tag strings\n  goodExamples String @map(\"good_examples\") // JSON array of code snippets\n  badExamples  String @map(\"bad_examples\") // JSON array of code snippets\n\n  authorId String @map(\"author_id\")\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  // 关联\n  revisions RuleRevision[]\n\n  @@map(\"rules\")\n}\n\n// ==========================================\n// 2. 规则修订记录表 (RuleRevision)\n// ==========================================\nmodel RuleRevision {\n  id             String @id @default(uuid())\n  ruleId         String @map(\"rule_id\")\n  revisionNumber Int    @map(\"revision_number\")\n\n  authorId       String  @map(\"author_id\")\n  changedFields  String  @map(\"changed_fields\") // JSON array\n  previousValues String? @map(\"previous_values\") // JSON object\n  newValues      String? @map(\"new_values\") // JSON object\n  changeType     String  @map(\"change_type\") // Created | Updated | Deprecated | Reactivated\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  // 关联\n  rule Rule @relation(fields: [ruleId], references: [id], onDelete: Cascade)\n\n  @@unique([ruleId, revisionNumber])\n  @@map(\"rule_revisions\")\n}\n\n// ==========================================\n// Notification Module\n// 通知聚合根、渠道、历史、偏好、模板\n// ==========================================\n\nmodel Notification {\n  id                String    @id\n  identityId        String    @map(\"identity_id\")\n  type              String\n  category          String\n  status            String\n  title             String\n  content           String\n  importance        String\n  urgency           String\n  relatedEntityType String?   @map(\"related_entity_type\")\n  relatedEntityId   String?   @map(\"related_entity_id\")\n  metadata          String?\n  actions           String?\n  readAt            DateTime? @map(\"read_at\")\n  sentAt            DateTime? @map(\"sent_at\")\n  expiresAt         DateTime? @map(\"expires_at\")\n  version           Int       @default(1)\n  createdAt         DateTime  @default(now()) @map(\"created_at\")\n  updatedAt         DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt         DateTime? @map(\"deleted_at\")\n  isRead            Boolean   @default(false) @map(\"is_read\")\n\n  channels NotificationChannel[]\n  history  NotificationHistory[]\n  account  Account               @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  @@index([status])\n  @@map(\"notifications\")\n}\n\nmodel NotificationChannel {\n  id             String  @id\n  identityId     String  @map(\"identity_id\")\n  notificationId String  @map(\"notification_id\")\n  channelType    String  @map(\"channel_type\")\n  status         String\n  recipient      String?\n  maxRetries     Int     @default(3) @map(\"max_retries\")\n  error          String?\n  response       String?\n  retryCount     Int     @default(0) @map(\"retry_count\")\n\n  identity     Account      @relation(\"AccountNotificationChannels\", fields: [identityId], references: [id])\n  notification Notification @relation(fields: [notificationId], references: [id], onDelete: Cascade)\n\n  @@index([identityId])\n  @@index([notificationId])\n  @@map(\"notification_channels\")\n}\n\nmodel NotificationHistory {\n  id             String   @id\n  identityId     String   @map(\"identity_id\")\n  notificationId String   @map(\"notification_id\")\n  action         String\n  details        String?\n  actorId        String?  @map(\"actor_id\")\n  createdAt      DateTime @default(now()) @map(\"created_at\")\n\n  identity     Account      @relation(\"AccountNotificationHistory\", fields: [identityId], references: [id])\n  notification Notification @relation(fields: [notificationId], references: [id], onDelete: Cascade)\n\n  @@index([identityId])\n  @@index([notificationId])\n  @@map(\"notification_history\")\n}\n\nmodel NotificationPreference {\n  id           String    @id\n  identityId   String    @unique @map(\"identity_id\")\n  enabled      Boolean   @default(true)\n  channels     String\n  categories   String\n  doNotDisturb String?   @map(\"do_not_disturb\")\n  rateLimit    String?   @map(\"rate_limit\")\n  version      Int       @default(1)\n  createdAt    DateTime  @default(now()) @map(\"created_at\")\n  updatedAt    DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt    DateTime? @map(\"deleted_at\")\n\n  @@index([identityId])\n  @@map(\"notification_preferences\")\n}\n\nmodel NotificationTemplate {\n  id              String   @id\n  name            String   @unique\n  displayName     String   @map(\"display_name\")\n  description     String?\n  type            String\n  category        String\n  titleTemplate   String   @map(\"title_template\")\n  contentTemplate String   @map(\"content_template\")\n  variables       String?\n  defaultActions  String?  @map(\"default_actions\")\n  isSystem        Boolean  @default(false) @map(\"is_system\")\n  isActive        Boolean  @default(true) @map(\"is_active\")\n  createdAt       DateTime @default(now()) @map(\"created_at\")\n  updatedAt       DateTime @updatedAt @map(\"updated_at\")\n\n  @@index([name])\n  @@map(\"notification_templates\")\n}\n\n// ==========================================\n// Reminder Module\n// 提醒模板、实例、分组、历史、统计、响应\n// ==========================================\n\nmodel ReminderTemplate {\n  id                 String    @id\n  identityId         String    @map(\"identity_id\")\n  name               String\n  description        String?\n  type               String\n  selfEnabled        Boolean   @map(\"self_enabled\")\n  status             String\n  reminderGroupId    String?   @map(\"reminder_group_id\")\n  importanceLevel    String    @map(\"importance_level\")\n  tags               String\n  color              String?\n  icon               String?\n  nextTriggerAt      DateTime? @map(\"next_trigger_at\")\n  version            Int       @default(1)\n  createdAt          DateTime  @default(now()) @map(\"created_at\")\n  updatedAt          DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt          DateTime? @map(\"deleted_at\")\n  trigger            String\n  recurrence         String?\n  activeTime         String    @map(\"active_time\")\n  activeHours        String?   @map(\"active_hours\")\n  notificationConfig String    @map(\"notification_config\")\n  stats              String\n\n  // Smart Frequency: Response Metrics\n  clickRate          Float?    @map(\"click_rate\")\n  ignoreRate         Float?    @map(\"ignore_rate\")\n  avgResponseTime    Int?      @map(\"avg_response_time\")\n  snoozeCount        Int       @default(0) @map(\"snooze_count\")\n  effectivenessScore Float?    @map(\"effectiveness_score\")\n  sampleSize         Int       @default(0) @map(\"sample_size\")\n  lastAnalysisTime   DateTime? @map(\"last_analysis_time\")\n\n  // Smart Frequency: Frequency Adjustment\n  originalInterval      Int?      @map(\"original_interval\")\n  adjustedInterval      Int?      @map(\"adjusted_interval\")\n  adjustmentReason      String?   @map(\"adjustment_reason\")\n  adjustmentTime        DateTime? @map(\"adjustment_time\")\n  isAutoAdjusted        Boolean   @default(false) @map(\"is_auto_adjusted\")\n  userConfirmed         Boolean   @default(false) @map(\"user_confirmed\")\n  smartFrequencyEnabled Boolean   @default(true) @map(\"smart_frequency_enabled\")\n\n  history   ReminderHistory[]\n  instances ReminderInstance[]\n  responses ReminderResponse[]\n  account   Account            @relation(fields: [identityId], references: [id], onDelete: Cascade)\n  group     ReminderGroup?     @relation(fields: [reminderGroupId], references: [id])\n\n  @@index([status])\n  @@map(\"reminder_templates\")\n}\n\nmodel ReminderGroup {\n  id          String    @id\n  identityId  String    @map(\"identity_id\")\n  name        String\n  description String?\n  color       String?\n  icon        String?\n  controlMode String    @map(\"control_mode\")\n  enabled     Boolean\n  status      String\n  order       Int\n  stats       String\n  version     Int       @default(1)\n  createdAt   DateTime  @default(now()) @map(\"created_at\")\n  updatedAt   DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt   DateTime? @map(\"deleted_at\")\n\n  account   Account            @relation(fields: [identityId], references: [id], onDelete: Cascade)\n  templates ReminderTemplate[]\n\n  @@index([identityId])\n  @@map(\"reminder_groups\")\n}\n\nmodel ReminderInstance {\n  id          String    @id\n  templateId  String    @map(\"template_id\")\n  identityId  String    @map(\"identity_id\")\n  triggerAt   DateTime  @map(\"trigger_at\")\n  status      String\n  result      String?\n  processedAt DateTime? @map(\"processed_at\")\n  note        String?\n  payload     String?\n  createdAt   DateTime  @default(now()) @map(\"created_at\")\n  updatedAt   DateTime  @updatedAt @map(\"updated_at\")\n\n  account  Account          @relation(fields: [identityId], references: [id], onDelete: NoAction, onUpdate: NoAction)\n  template ReminderTemplate @relation(fields: [templateId], references: [id], onDelete: Cascade)\n\n  @@index([triggerAt])\n  @@map(\"reminder_instances\")\n}\n\nmodel ReminderHistory {\n  id                  String   @id\n  identityId          String   @map(\"identity_id\")\n  templateId          String   @map(\"template_id\")\n  triggeredAt         DateTime @map(\"triggered_at\")\n  result              String\n  error               String?\n  notificationSent    Boolean  @map(\"notification_sent\")\n  notificationChannel String?\n  createdAt           DateTime @default(now()) @map(\"created_at\")\n\n  identity Account          @relation(\"AccountReminderHistory\", fields: [identityId], references: [id])\n  template ReminderTemplate @relation(fields: [templateId], references: [id], onDelete: Cascade)\n\n  @@index([identityId])\n  @@index([templateId])\n  @@map(\"reminder_history\")\n}\n\nmodel ReminderStatistic {\n  id            String   @id\n  identityId    String   @unique @map(\"identity_id\")\n  templateStats String   @map(\"template_stats\")\n  groupStats    String   @map(\"group_stats\")\n  triggerStats  String   @map(\"trigger_stats\")\n  calculatedAt  DateTime @map(\"calculated_at\")\n\n  account Account @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  @@index([identityId])\n  @@map(\"reminder_statistics\")\n}\n\nmodel ReminderResponse {\n  id           String   @id @default(uuid())\n  identityId   String   @map(\"identity_id\")\n  templateId   String   @map(\"template_id\")\n  action       String // clicked, ignored, snoozed, dismissed, completed\n  responseTime Int?     @map(\"response_time\") // seconds\n  timestamp    DateTime\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n\n  identity Account          @relation(\"AccountReminderResponses\", fields: [identityId], references: [id])\n  template ReminderTemplate @relation(fields: [templateId], references: [id], onDelete: Cascade)\n\n  @@index([identityId])\n  @@index([templateId, timestamp(sort: Desc)])\n  @@map(\"reminder_responses\")\n}\n\n/// UserReminderPreference 聚合根 - 用户提醒偏好\n/// 存储用户的最佳/最差响应时间段和智能频率配置\nmodel UserReminderPreference {\n  // ============ 主键与外键 ============\n  id         String @id\n  identityId String @unique @map(\"identity_id\")\n\n  // ============ 时间段偏好 ============\n  bestTimeSlots  String @map(\"best_time_slots\") /// JSON: TimeSlotDTO[]\n  worstTimeSlots String @map(\"worst_time_slots\") /// JSON: TimeSlotDTO[]\n\n  // ============ 智能频率 ============\n  globalSmartFrequency Boolean @default(true) @map(\"global_smart_frequency\")\n\n  // ============ 审计 ============\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  // ============ 关系映射 ============\n  account Account @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  // ============ 索引优化 ============\n  @@index([identityId])\n  @@map(\"user_reminder_preferences\")\n}\n\n// ==========================================\n// Repository Module\n// 仓库聚合根、资源、文件夹、浏览器、统计\n// ==========================================\n\nmodel Repository {\n  id             String    @id\n  identityId     String    @map(\"identity_id\")\n  name           String\n  type           String\n  path           String\n  description    String?\n  config         Json      @default(\"{}\") // RepositoryConfig JSONB\n  stats          Json      @default(\"{}\") // RepositoryStats JSONB\n  relatedGoals   String?   @map(\"related_goals\")\n  status         String    @default(\"ACTIVE\") // ACTIVE | ARCHIVED | DELETED\n  git            String?\n  syncStatus     String?   @map(\"sync_status\")\n  lastAccessedAt DateTime? @map(\"last_accessed_at\")\n  version        Int       @default(1)\n  createdAt      DateTime  @default(now()) @map(\"created_at\")\n  updatedAt      DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt      DateTime? @map(\"deleted_at\")\n\n  account             Account              @relation(fields: [identityId], references: [id], onDelete: Cascade)\n  explorers           RepositoryExplorer[]\n  repositoryResources RepositoryResource[]\n  resources           Resource[]\n  folders             Folder[]\n\n  @@unique([identityId, path])\n  @@index([type])\n  @@index([status])\n  @@map(\"repositories\")\n}\n\nmodel Folder {\n  id           String   @id\n  identityId   String   @map(\"identity_id\")\n  repositoryId String   @map(\"repository_id\")\n  parentId     String?  @map(\"parent_id\")\n  name         String\n  path         String // Auto-generated: /parent/name\n  order        Int      @default(0)\n  isExpanded   Boolean  @default(true) @map(\"is_expanded\")\n  metadata     Json     @default(\"{}\") // FolderMetadata JSONB\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n  updatedAt    DateTime @updatedAt @map(\"updated_at\")\n\n  identity   Account    @relation(\"AccountFolders\", fields: [identityId], references: [id])\n  repository Repository @relation(fields: [repositoryId], references: [id], onDelete: Cascade)\n  parent     Folder?    @relation(\"FolderHierarchy\", fields: [parentId], references: [id], onDelete: Cascade)\n  children   Folder[]   @relation(\"FolderHierarchy\")\n\n  @@unique([repositoryId, parentId, name])\n  @@index([identityId])\n  @@index([repositoryId])\n  @@index([parentId])\n  @@index([path])\n  @@map(\"folders\")\n}\n\nmodel Resource {\n  id           String    @id\n  identityId   String    @map(\"identity_id\")\n  repositoryId String    @map(\"repository_id\")\n  folderId     String?   @map(\"folder_id\")\n  name         String\n  type         String // markdown | image | video | audio | pdf | link | code | other\n  path         String\n  size         Int       @default(0)\n  content      String?   @db.Text\n  metadata     Json      @default(\"{}\") // ResourceMetadata\n  stats        Json      @default(\"{}\") // ResourceStats\n  description  String?\n  author       String?\n  version      String?\n  tags         String    @default(\"[]\") // JSON array\n  category     String?\n  status       String    @default(\"ACTIVE\") // ACTIVE | ARCHIVED | DELETED | DRAFT\n  createdAt    DateTime  @default(now()) @map(\"created_at\")\n  updatedAt    DateTime  @updatedAt @map(\"updated_at\")\n  modifiedAt   DateTime? @map(\"modified_at\")\n  deletedAt    DateTime? @map(\"deleted_at\")\n\n  identity   Account    @relation(\"AccountResources\", fields: [identityId], references: [id])\n  repository Repository @relation(fields: [repositoryId], references: [id], onDelete: Cascade)\n\n  @@index([identityId])\n  @@index([repositoryId])\n  @@index([folderId])\n  @@index([type])\n  @@index([status])\n  @@index([category])\n  @@index([createdAt])\n  @@map(\"resources\")\n}\n\nmodel RepositoryResource {\n  id           String    @id\n  identityId   String    @map(\"identity_id\")\n  repositoryId String    @map(\"repository_id\")\n  name         String\n  type         String\n  path         String\n  size         Int?\n  description  String?\n  author       String?\n  version      String?\n  tags         String?\n  category     String?\n  status       String    @default(\"active\")\n  metadata     String?\n  createdAt    DateTime  @default(now()) @map(\"created_at\")\n  updatedAt    DateTime  @updatedAt @map(\"updated_at\")\n  modifiedAt   DateTime? @map(\"modified_at\")\n\n  linkedContents LinkedContent[]\n  identity       Account             @relation(\"AccountRepositoryResources\", fields: [identityId], references: [id])\n  repository     Repository          @relation(fields: [repositoryId], references: [id], onDelete: Cascade)\n  sourceRefs     ResourceReference[] @relation(\"SourceResourceRefs\")\n  targetRefs     ResourceReference[] @relation(\"TargetResourceRefs\")\n\n  @@unique([repositoryId, path])\n  @@index([identityId])\n  @@index([type])\n  @@map(\"repository_resources\")\n}\n\nmodel LinkedContent {\n  id            String    @id\n  resourceId    String    @map(\"resource_id\")\n  title         String\n  url           String\n  contentType   String    @map(\"content_type\")\n  description   String?\n  thumbnail     String?\n  author        String?\n  publishedAt   DateTime? @map(\"published_at\")\n  isAccessible  Boolean   @default(true) @map(\"is_accessible\")\n  lastCheckedAt DateTime? @map(\"last_checked_at\")\n  cachedAt      DateTime? @map(\"cached_at\")\n  createdAt     DateTime  @default(now()) @map(\"created_at\")\n  updatedAt     DateTime  @updatedAt @map(\"updated_at\")\n\n  repositoryResource RepositoryResource @relation(fields: [resourceId], references: [id], onDelete: Cascade)\n\n  @@index([url])\n  @@map(\"linked_contents\")\n}\n\nmodel ResourceReference {\n  id               String    @id\n  sourceResourceId String    @map(\"source_resource_id\")\n  targetResourceId String    @map(\"target_resource_id\")\n  referenceType    String    @map(\"reference_type\")\n  description      String?\n  createdAt        DateTime  @default(now()) @map(\"created_at\")\n  updatedAt        DateTime  @updatedAt @map(\"updated_at\")\n  lastVerifiedAt   DateTime? @map(\"last_verified_at\")\n\n  sourceResource RepositoryResource @relation(\"SourceResourceRefs\", fields: [sourceResourceId], references: [id], onDelete: Cascade)\n  targetResource RepositoryResource @relation(\"TargetResourceRefs\", fields: [targetResourceId], references: [id], onDelete: Cascade)\n\n  @@unique([sourceResourceId, targetResourceId, referenceType])\n  @@index([targetResourceId])\n  @@map(\"resource_references\")\n}\n\nmodel RepositoryExplorer {\n  id           String    @id\n  repositoryId String    @map(\"repository_id\")\n  identityId   String    @map(\"identity_id\")\n  name         String\n  description  String?\n  currentPath  String    @map(\"current_path\")\n  filters      String?\n  viewConfig   String?   @map(\"view_config\")\n  pinnedPaths  String?   @map(\"pinned_paths\")\n  recentPaths  String?   @map(\"recent_paths\")\n  lastScanAt   DateTime? @map(\"last_scan_at\")\n  createdAt    DateTime  @default(now()) @map(\"created_at\")\n  updatedAt    DateTime  @updatedAt @map(\"updated_at\")\n\n  account    Account    @relation(fields: [identityId], references: [id], onDelete: Cascade)\n  repository Repository @relation(fields: [repositoryId], references: [id], onDelete: Cascade)\n\n  @@unique([repositoryId, identityId])\n  @@index([repositoryId])\n  @@map(\"repository_explorers\")\n}\n\nmodel RepositoryStatistic {\n  id                   Int      @id @default(autoincrement())\n  identityId           String   @unique @map(\"identity_id\")\n  totalRepositories    Int      @default(0) @map(\"total_repositories\")\n  activeRepositories   Int      @default(0) @map(\"active_repositories\")\n  archivedRepositories Int      @default(0) @map(\"archived_repositories\")\n  totalResources       Int      @default(0) @map(\"total_resources\")\n  totalFiles           Int      @default(0) @map(\"total_files\")\n  totalFolders         Int      @default(0) @map(\"total_folders\")\n  gitEnabledRepos      Int      @default(0) @map(\"git_enabled_repos\")\n  totalCommits         Int      @default(0) @map(\"total_commits\")\n  totalReferences      Int      @default(0) @map(\"total_references\")\n  totalLinkedContents  Int      @default(0) @map(\"total_linked_contents\")\n  totalSizeBytes       BigInt   @default(0) @map(\"total_size_bytes\")\n  lastUpdatedAt        DateTime @default(now()) @map(\"last_updated_at\")\n  createdAt            DateTime @default(now()) @map(\"created_at\")\n\n  account Account @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  @@index([identityId])\n  @@map(\"repository_statistics\")\n}\n\n// ==========================================\n// Schedule Module\n// 日程聚合根、调度任务、调度作业、执行、统计\n// ==========================================\n\nmodel Schedule {\n  id                   String   @id\n  identityId           String   @map(\"identity_id\")\n  title                String\n  description          String?\n  startTime            DateTime @map(\"start_time\")\n  endTime              DateTime @map(\"end_time\")\n  duration             Int\n  hasConflict          Boolean  @default(false) @map(\"has_conflict\")\n  conflictingSchedules String?  @map(\"conflicting_schedules\")\n  priority             Int?\n  location             String?\n  attendees            String?\n  createdAt            DateTime @default(now()) @map(\"created_at\")\n  updatedAt            DateTime @updatedAt @map(\"updated_at\")\n\n  account Account @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  @@index([startTime, endTime])\n  @@map(\"schedules\")\n}\n\n/// ScheduleJob 聚合根 - 调度作业\n/// 跨模块的调度触发器，关联到业务模块的具体资源\nmodel ScheduleJob {\n  // ============ 主键与外键 ============\n  id         String @id\n  identityId String @map(\"identity_id\")\n\n  // ============ 调度配置 ============\n  nextRunAt      DateTime @map(\"next_run_at\")\n  cronExpression String?  @map(\"cron_expression\")\n\n  // ============ 来源 ============\n  sourceModule String @map(\"source_module\") /// 来源模块\n  sourceId     String @map(\"source_id\") /// 来源实体ID\n\n  // ============ 触发配置 ============\n  triggerEvent String  @map(\"trigger_event\")\n  payload      String? /// JSON: Record<string, any>\n\n  // ============ 审计 ============\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  // ============ 关系映射 ============\n  account Account @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  // ============ 索引优化 ============\n  @@index([identityId])\n  @@index([nextRunAt])\n  @@index([sourceModule, sourceId])\n  @@map(\"schedule_jobs\")\n}\n\nmodel ScheduleTask {\n  id                    String    @id\n  identityId            String    @map(\"identity_id\")\n  name                  String\n  description           String?\n  sourceModule          String    @map(\"source_module\")\n  sourceEntityId        String    @map(\"source_entity_id\")\n  status                String\n  enabled               Boolean\n  cronExpression        String?   @map(\"cron_expression\")\n  timezone              String\n  startDate             DateTime? @map(\"start_date\")\n  endDate               DateTime? @map(\"end_date\")\n  maxExecutions         Int?      @map(\"max_executions\")\n  nextRunAt             DateTime? @map(\"next_run_at\")\n  lastRunAt             DateTime? @map(\"last_run_at\")\n  executionCount        Int       @default(0) @map(\"execution_count\")\n  lastExecutionStatus   String?   @map(\"last_execution_status\")\n  lastExecutionDuration Int?      @map(\"last_execution_duration\")\n  consecutiveFailures   Int       @default(0) @map(\"consecutive_failures\")\n  maxRetries            Int       @map(\"max_retries\")\n  initialDelayMs        Int       @map(\"initial_delay_ms\")\n  maxDelayMs            Int       @map(\"max_delay_ms\")\n  backoffMultiplier     Float     @map(\"backoff_multiplier\")\n  retryableStatuses     String    @default(\"[]\") @map(\"retryable_statuses\")\n  payload               String?\n  tags                  String    @default(\"[]\")\n  priority              String\n  timeout               Int?\n  version               Int       @default(1)\n  createdAt             DateTime  @default(now()) @map(\"created_at\")\n  updatedAt             DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt             DateTime? @map(\"deleted_at\")\n\n  executions ScheduleExecution[]\n  account    Account             @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  @@index([status])\n  @@map(\"schedule_tasks\")\n}\n\nmodel ScheduleExecution {\n  id            String   @id\n  identityId    String   @map(\"identity_id\")\n  taskId        String   @map(\"task_id\")\n  executionTime DateTime @map(\"execution_time\")\n  status        String\n  duration      Int?\n  result        String?\n  error         String?\n  retryCount    Int      @default(0) @map(\"retry_count\")\n  createdAt     DateTime @default(now()) @map(\"created_at\")\n\n  identity Account      @relation(\"AccountScheduleExecutions\", fields: [identityId], references: [id])\n  task     ScheduleTask @relation(fields: [taskId], references: [id], onDelete: Cascade)\n\n  @@index([identityId])\n  @@index([taskId])\n  @@map(\"schedule_executions\")\n}\n\nmodel ScheduleStatistic {\n  id                   Int      @id @default(autoincrement())\n  identityId           String   @unique @map(\"identity_id\")\n  totalTasks           Int      @map(\"total_tasks\")\n  activeTasks          Int      @map(\"active_tasks\")\n  pausedTasks          Int      @map(\"paused_tasks\")\n  completedTasks       Int      @map(\"completed_tasks\")\n  cancelledTasks       Int      @map(\"cancelled_tasks\")\n  failedTasks          Int      @map(\"failed_tasks\")\n  totalExecutions      Int      @map(\"total_executions\")\n  successfulExecutions Int      @map(\"successful_executions\")\n  failedExecutions     Int      @map(\"failed_executions\")\n  skippedExecutions    Int      @map(\"skipped_executions\")\n  timeoutExecutions    Int      @map(\"timeout_executions\")\n  avgExecutionDuration Float    @map(\"avg_execution_duration\")\n  minExecutionDuration Float    @map(\"min_execution_duration\")\n  maxExecutionDuration Float    @map(\"max_execution_duration\")\n  moduleStatistics     String   @default(\"{}\") @map(\"module_statistics\")\n  lastUpdatedAt        DateTime @map(\"last_updated_at\")\n  createdAt            DateTime @default(now()) @map(\"created_at\")\n\n  account Account @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  @@index([identityId])\n  @@map(\"schedule_statistics\")\n}\n\n// ==========================================\n// Setting Module\n// User settings with JSONB preferences storage\n// ==========================================\n\nmodel UserSetting {\n  id          String   @id @default(uuid())\n  identityId  String   @unique @map(\"identity_id\")\n  preferences Json     @default(\"{}\")\n  version     Int      @default(1)\n  createdAt   DateTime @default(now()) @map(\"created_at\")\n  updatedAt   DateTime @updatedAt @map(\"updated_at\")\n\n  account Account @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  @@index([identityId])\n  @@map(\"user_settings\")\n}\n\n// ==========================================\n// Task Module\n// 任务模板聚合根、实例、文件夹、依赖、历史、统计\n// ==========================================\n\n/// TaskFolder 聚合根 - 任务文件夹\n/// 用于组织和分类任务模板\nmodel TaskFolder {\n  // ============ 主键与外键 ============\n  id         String @id\n  identityId String @map(\"identity_id\")\n\n  // ============ 基础信息 ============\n  name  String /// 文件夹名称\n  color String? /// 显示颜色\n  icon  String? /// 图标标识\n\n  // ============ 排序 ============\n  order Int @default(0) /// 排序顺序\n\n  // ============ 版本与审计 ============\n  version   Int       @default(1)\n  createdAt DateTime  @default(now()) @map(\"created_at\")\n  updatedAt DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt DateTime? @map(\"deleted_at\")\n\n  // ============ 关系映射 ============\n  account   Account        @relation(fields: [identityId], references: [id], onDelete: Cascade)\n  templates TaskTemplate[]\n\n  // ============ 索引优化 ============\n  @@index([identityId])\n  @@map(\"task_folders\")\n}\n\n/// TaskTemplate 聚合根 - 任务模板\n/// 管理任务的完整定义，包括时间配置、重复规则、提醒、Goal绑定等\nmodel TaskTemplate {\n  // ============ 主键与外键 ============\n  id         String @id\n  identityId String @map(\"identity_id\")\n\n  // ============ 基础信息 ============\n  name        String\n  description String?\n  status      String /// TaskTemplateStatus\n  importance  String  @default(\"moderate\") /// ImportanceLevel\n  priority    Int? /// 动态计算的优先级分数\n  color       String?\n  tags        String /// JSON: string[]\n\n  // ============ 组织与层级 ============\n  folderId     String? @map(\"folder_id\")\n  parentTaskId String? @map(\"parent_task_id\")\n\n  // ============ 时间配置（展开值对象） ============\n  timeConfigType            String?   @map(\"time_config_type\")\n  timeConfigStartTime       DateTime? @map(\"time_config_start_time\")\n  timeConfigEndTime         DateTime? @map(\"time_config_end_time\")\n  timeConfigDurationMinutes Int?      @map(\"time_config_duration_minutes\")\n  timeConfigTimePoint       Int?      @map(\"time_config_time_point\") /// 时间点（分钟数，如 540 = 9:00）\n  timeConfigTimeRangeStart  Int?      @map(\"time_config_time_range_start\") /// 时间段开始（分钟数）\n  timeConfigTimeRangeEnd    Int?      @map(\"time_config_time_range_end\") /// 时间段结束（分钟数）\n\n  // ============ 重复规则（展开值对象） ============\n  recurrenceRuleType        String?   @map(\"recurrence_rule_type\")\n  recurrenceRuleInterval    Int?      @map(\"recurrence_rule_interval\")\n  recurrenceRuleDaysOfWeek  String?   @map(\"recurrence_rule_days_of_week\")\n  recurrenceRuleDayOfMonth  Int?      @map(\"recurrence_rule_day_of_month\")\n  recurrenceRuleMonthOfYear Int?      @map(\"recurrence_rule_month_of_year\")\n  recurrenceRuleEndDate     DateTime? @map(\"recurrence_rule_end_date\")\n  recurrenceRuleCount       Int?      @map(\"recurrence_rule_count\")\n\n  // ============ 提醒配置（展开值对象） ============\n  reminderConfigEnabled           Boolean? @map(\"reminder_config_enabled\")\n  reminderConfigTimeOffsetMinutes Int?     @map(\"reminder_config_time_offset_minutes\")\n  reminderConfigUnit              String?  @map(\"reminder_config_unit\")\n  reminderConfigChannel           String?  @map(\"reminder_config_channel\")\n\n  // ============ 循环任务生成 ============\n  lastGeneratedDate DateTime? @map(\"last_generated_date\")\n  generateAheadDays Int?      @map(\"generate_ahead_days\")\n\n  // ============ Goal 绑定（JSON值对象） ============\n  goalBinding String? @map(\"goal_binding\") /// JSON: TaskGoalBindingPersistenceDTO\n\n  // ============ 检查列表（JSON值对象） ============\n  checklist String? @map(\"checklist\") /// JSON: ChecklistItemDefinition[]\n\n  // ============ 依赖关系状态 ============\n  blockingReason   String? @map(\"blocking_reason\")\n  dependencyStatus String  @default(\"NONE\") @map(\"dependency_status\")\n  isBlocked        Boolean @default(false) @map(\"is_blocked\")\n\n  // ============ 版本与审计 ============\n  version   Int       @default(1)\n  createdAt DateTime  @default(now()) @map(\"created_at\")\n  updatedAt DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt DateTime? @map(\"deleted_at\")\n\n  // ============ 关系映射 ============\n  account Account     @relation(fields: [identityId], references: [id], onDelete: Cascade)\n  folder  TaskFolder? @relation(fields: [folderId], references: [id], onDelete: SetNull)\n\n  // 子任务关系\n  parentTask TaskTemplate?  @relation(\"TaskSubtasks\", fields: [parentTaskId], references: [id], onDelete: SetNull)\n  subtasks   TaskTemplate[] @relation(\"TaskSubtasks\")\n\n  // 依赖关系\n  predecessorDependencies TaskDependency[] @relation(\"PredecessorTaskDeps\")\n  successorDependencies   TaskDependency[] @relation(\"SuccessorTaskDeps\")\n\n  // 实例\n  instances TaskInstance[]\n  history   TaskTemplateHistory[]\n\n  // ============ 索引优化 ============\n  @@index([identityId])\n  @@index([status])\n  @@index([importance])\n  @@index([folderId])\n  @@index([parentTaskId])\n  @@index([deletedAt])\n  @@map(\"task_templates\")\n}\n\n/// TaskInstance 聚合根 - 任务实例\n/// 从模板生成的具体任务实例，包含执行状态和时间追踪\nmodel TaskInstance {\n  // ============ 主键与外键 ============\n  id         String @id\n  templateId String @map(\"template_id\")\n  identityId String @map(\"identity_id\")\n\n  // ============ 实例基本信息 ============\n  instanceDate DateTime @map(\"instance_date\")\n  status       String /// TaskInstanceStatus\n  importance   String   @default(\"moderate\") /// ImportanceLevel\n  priority     Int? /// 动态计算的优先级分数\n\n  // ============ 时间追踪 ============\n  timeConfig      String    @map(\"time_config\") /// JSON: TaskTimeConfigDTO\n  actualStartTime DateTime? @map(\"actual_start_time\")\n  actualEndTime   DateTime? @map(\"actual_end_time\")\n\n  // ============ 备注 ============\n  comment String? /// 实例备注\n\n  // ============ 版本与审计 ============\n  version   Int       @default(1)\n  createdAt DateTime  @default(now()) @map(\"created_at\")\n  updatedAt DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt DateTime? @map(\"deleted_at\")\n\n  // ============ 关系映射 ============\n  account  Account      @relation(fields: [identityId], references: [id], onDelete: NoAction, onUpdate: NoAction)\n  template TaskTemplate @relation(fields: [templateId], references: [id], onDelete: Cascade)\n\n  // ============ 索引优化 ============\n  @@index([templateId, instanceDate])\n  @@index([identityId, status])\n  @@index([identityId, instanceDate])\n  @@map(\"task_instances\")\n}\n\nmodel TaskDependency {\n  id                String    @id\n  identityId        String    @map(\"identity_id\")\n  predecessorTaskId String    @map(\"predecessor_task_id\")\n  successorTaskId   String    @map(\"successor_task_id\")\n  dependencyType    String    @default(\"FINISH_TO_START\") @map(\"dependency_type\")\n  lagDays           Int?      @map(\"lag_days\")\n  version           Int       @default(1)\n  createdAt         DateTime  @default(now()) @map(\"created_at\")\n  updatedAt         DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt         DateTime? @map(\"deleted_at\")\n\n  identity        Account      @relation(\"AccountTaskDependencies\", fields: [identityId], references: [id])\n  predecessorTask TaskTemplate @relation(\"PredecessorTaskDeps\", fields: [predecessorTaskId], references: [id], onDelete: Cascade)\n  successorTask   TaskTemplate @relation(\"SuccessorTaskDeps\", fields: [successorTaskId], references: [id], onDelete: Cascade)\n\n  @@unique([predecessorTaskId, successorTaskId])\n  @@index([identityId])\n  @@index([successorTaskId])\n  @@map(\"task_dependencies\")\n}\n\nmodel TaskTemplateHistory {\n  id         String   @id\n  identityId String   @map(\"identity_id\")\n  templateId String   @map(\"template_id\")\n  action     String\n  changes    String?\n  createdAt  DateTime @default(now()) @map(\"created_at\")\n\n  identity Account      @relation(\"AccountTaskTemplateHistory\", fields: [identityId], references: [id])\n  template TaskTemplate @relation(fields: [templateId], references: [id], onDelete: Cascade)\n\n  @@index([identityId])\n  @@index([templateId])\n  @@map(\"task_template_history\")\n}\n\nmodel TaskStatistic {\n  id                       String   @id\n  identityId               String   @unique @map(\"identity_id\")\n  calculatedAt             DateTime @map(\"calculated_at\")\n  templateTotal            Int      @map(\"template_total\")\n  templateActive           Int      @map(\"template_active\")\n  templatePaused           Int      @map(\"template_paused\")\n  templateArchived         Int      @map(\"template_archived\")\n  templateOneTime          Int      @map(\"template_one_time\")\n  templateRecurring        Int      @map(\"template_recurring\")\n  instanceTotal            Int      @map(\"instance_total\")\n  instanceToday            Int      @map(\"instance_today\")\n  instanceWeek             Int      @map(\"instance_week\")\n  instanceMonth            Int      @map(\"instance_month\")\n  instancePending          Int      @map(\"instance_pending\")\n  instanceInProgress       Int      @map(\"instance_in_progress\")\n  instanceCompleted        Int      @map(\"instance_completed\")\n  instanceSkipped          Int      @map(\"instance_skipped\")\n  instanceExpired          Int      @map(\"instance_expired\")\n  completionToday          Int      @map(\"completion_today\")\n  completionWeek           Int      @map(\"completion_week\")\n  completionMonth          Int      @map(\"completion_month\")\n  completionTotal          Int      @map(\"completion_total\")\n  completionAvgTime        Float?   @map(\"completion_avg_time\")\n  completionRate           Float    @map(\"completion_rate\")\n  timeAllDay               Int      @map(\"time_all_day\")\n  timePoint                Int      @map(\"time_point\")\n  timeRange                Int      @map(\"time_range\")\n  timeOverdue              Int      @map(\"time_overdue\")\n  timeUpcoming             Int      @map(\"time_upcoming\")\n  distributionByImportance String   @map(\"distribution_by_importance\")\n  distributionByUrgency    String   @map(\"distribution_by_urgency\")\n  distributionByFolder     String   @map(\"distribution_by_folder\")\n  distributionByTag        String   @map(\"distribution_by_tag\")\n\n  account Account @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  @@index([identityId])\n  @@map(\"task_statistics\")\n}\n"
}

